package com.oms.order.service;

import com.oms.common.api.OrderStockClient;
import com.oms.common.model.dto.OrderStockCommand;
import com.ruoyi.common.core.constant.SecurityConstants;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import javax.annotation.Resource;
import java.math.BigDecimal;
import java.util.*;
import static com.oms.order.service.OrderValues.*;
import static com.oms.order.service.GiftRules.*;

/** Immutable initial entitlement, current eligibility and actual inventory facts are separate. */
@Service public class GiftService {
    @Resource OrderRepository repository;
    @Resource OrderCatalog catalog;
    @Resource OrderWarehouseClient inventory;
    @Resource OrderCutoffService cutoffs;
    private volatile long cacheUntil;
    private final Map<String,List<Map<String,Object>>> cache=new HashMap<>();
    TransactionTemplate tx(){return new TransactionTemplate(new DataSourceTransactionManager(repository.db().getDataSource()));}
    public List<Map<String,Object>> groups(String company){List<Map<String,Object>> rows=repository.db().query("SELECT * FROM oms_gift_group WHERE company_code=? ORDER BY priority,id",ROW,company);for(Map<String,Object> r:rows)r.put("policy",object(r.get("policy")));return rows;}
    synchronized List<Map<String,Object>> published(String company){long now=System.currentTimeMillis();if(now>=cacheUntil){cache.clear();cacheUntil=now+5000;}return cache.computeIfAbsent(company,c->{List<Map<String,Object>> all=groups(c);all.removeIf(g->number(g,"enabled")!=1);return all;});}
    public Map<String,Object> save(String company,Map<String,Object> input,String actor){
        String name=required(input,"name",100);long priority=number(input,"priority"),enabled=number(input,"enabled"),id=number(input,"id");require(priority>=1&&priority<=100000&&enabled>=0&&enabled<=1,"优先级或状态无效");Map<String,Object> p=normalize(object(input.get("policy")));
        Set<String> all=new LinkedHashSet<>(),gifts=new LinkedHashSet<>();for(Map<String,Object> r:rows(p.get("rules"))){for(Object sku:(List<?>)r.get("skus"))all.add(String.valueOf(sku));for(Map<String,Object> g:rows(r.get("gifts")))gifts.add(text(g,"sku_sn"));for(Map<String,Object> t:rows(r.get("tiers")))for(Map<String,Object> g:rows(t.get("gifts")))gifts.add(text(g,"sku_sn"));}all.addAll(gifts);
        require(all.size()<=200,"一个策略组最多涉及200种购买或赠品SKU，请收敛策略范围");Map<String,List<Map<String,Object>>> products=catalog.goods(company,new ArrayList<>(all));for(String sku:all){require(products.getOrDefault(sku,Collections.emptyList()).size()==1,"SKU不存在或不唯一："+sku);if(gifts.contains(sku)){Map<String,Object> g=products.get(sku).get(0);require(number(g,"is_fd")==0&&(number(g,"is_package")==0||"STOCKED".equals(text(g,"inventory_mode"))),"赠品须选择可独立管理库存的实物SKU："+sku);}}
        Set<String> shops=new HashSet<>();for(Map<String,Object> shop:catalog.channels(company))if(number(shop,"enabled")==1)shops.add(text(shop,"channel_id"));for(Object shop:(List<?>)p.get("channels"))require(shops.contains(String.valueOf(shop)),"适用店铺不存在、已停用或不属于当前公司");
        long key=tx().execute(s->{long current=id;if(current==0){require(repository.db().queryForObject("SELECT COUNT(*) FROM oms_gift_group WHERE company_code=?",Long.class,company)<200,"每公司最多200个赠品策略组");current=repository.insert("INSERT INTO oms_gift_group(company_code,name,priority,enabled,policy,updated_by) VALUES (?,?,?,?,?,?)",company,name,priority,enabled,encode(p),actor);}
            else{List<Map<String,Object>> old=repository.db().query("SELECT revision FROM oms_gift_group WHERE company_code=? AND id=? FOR UPDATE",ROW,company,id);require(old.size()==1&&number(old.get(0),"revision")==number(input,"revision"),"策略组不存在或已变化，请刷新");repository.db().update("UPDATE oms_gift_group SET name=?,priority=?,enabled=?,policy=?,updated_by=?,revision=revision+1 WHERE company_code=? AND id=?",name,priority,enabled,encode(p),actor,company,id);}
            Map<String,Object> saved=repository.db().query("SELECT * FROM oms_gift_group WHERE company_code=? AND id=?",ROW,company,current).get(0);repository.db().update("INSERT INTO oms_gift_group_version(company_code,group_id,revision,snapshot,actor) VALUES (?,?,?,?,?)",company,current,saved.get("revision"),encode(saved),actor);return current;});synchronized(this){cache.remove(company);}return map("id",key);
    }
    List<Map<String,Object>> prepare(String company,Map<String,Object> platform,TmallOrderParser.Trade trade,Map<String,String> matched){
        List<Map<String,Object>> existing=repository.db().query("SELECT * FROM oms_gift_plan WHERE company_code=? AND platform_order_id=?",ROW,company,platform.get("id"));if(!existing.isEmpty())return initial(existing.get(0));
        List<Map<String,Object>> active=published(company);if(active.isEmpty())return Collections.emptyList();
        List<Map<String,Object>> basis=new ArrayList<>();for(TmallOrderParser.Line l:trade.lines)basis.add(map("platform_oid",l.oid,"sku_sn",matched.get(l.oid),"quantity",l.quantity,"payment",l.payment));
        String paid=paidTime(text(platform,"processing_payload"));Map<String,Object> result=evaluate(active,number(platform,"channel_id"),paid,basis);
        if(rows(result.get("gifts")).isEmpty())return Collections.emptyList();
        return tx().execute(s->{Map<String,Object> current=repository.raw(company,number(platform,"id"));require(text(current,"processing_hash").equals(text(platform,"processing_hash"))&&number(current,"change_pending")==0,"订单版本已变化，请重新处理赠品");repository.db().update("INSERT IGNORE INTO oms_gift_plan(company_code,platform_order_id,channel_id,snapshot,basis_json,initial_json) VALUES (?,?,?,?,?,?)",company,platform.get("id"),platform.get("channel_id"),encode(result),encode(basis),encode(result.get("gifts")));return initial(repository.db().query("SELECT * FROM oms_gift_plan WHERE company_code=? AND platform_order_id=?",ROW,company,platform.get("id")).get(0));});
    }
    static String paidTime(String payload){try{String paid=JSON.readTree(payload).path("trade_fullinfo_get_response").path("trade").path("pay_time").asText("");require(!paid.isEmpty(),"订单缺少付款时间，不能判断赠品活动范围");return paid;}catch(java.io.IOException e){throw new IllegalArgumentException("付款时间无法读取");}}
    private List<Map<String,Object>> initial(Map<String,Object> plan){List<Map<String,Object>> list=jsonRows(plan.get("initial_json"));for(Map<String,Object> row:list)row.put("gift_plan_id",plan.get("id"));return list;}
    List<Map<String,Object>> prepared(String company,long platform){List<Map<String,Object>> plans=repository.db().query("SELECT * FROM oms_gift_plan WHERE company_code=? AND platform_order_id=?",ROW,company,platform);return plans.isEmpty()?Collections.emptyList():initial(plans.get(0));}
    void bind(String company,long platform,long order){repository.db().update("UPDATE oms_gift_plan SET order_id=? WHERE company_code=? AND platform_order_id=? AND order_id IS NULL",order,company,platform);repository.db().update("UPDATE oms_order o JOIN oms_gift_plan p ON p.company_code=o.company_code AND p.order_id=o.id SET o.gift_plan_id=p.id WHERE o.company_code=? AND o.id=?",company,order);}
    static List<Map<String,Object>> jsonRows(Object json){try{return rows(JSON.readValue(String.valueOf(json),List.class));}catch(Exception e){throw new IllegalArgumentException("赠品台账明细无法读取");}}
    Map<String,Object> plan(String c,long order,boolean lock){List<Map<String,Object>> list=repository.db().query("SELECT * FROM oms_gift_plan WHERE company_code=? AND order_id=?"+(lock?" FOR UPDATE":""),ROW,c,order);return list.isEmpty()?null:list.get(0);}
    void event(String c,long plan,String action,String message,String actor){repository.db().update("INSERT INTO oms_gift_event(company_code,plan_id,action,message,actor) VALUES (?,?,?,?,?)",c,plan,action,message.substring(0,Math.min(1000,message.length())),actor);}
    /** Called within existing order/refund locks; no network I/O and no stock changes. */
    public Map<String,Object> assess(String c,long order){repository.db().query("SELECT id FROM oms_order WHERE company_code=? AND id=? FOR UPDATE",ROW,c,order);Map<String,Object> p=plan(c,order,true);if(p==null)return map("available",false,"lines",Collections.emptyList());
        List<Map<String,Object>> basis=jsonRows(p.get("basis_json")),effective=new ArrayList<>(),projected=new ArrayList<>(),refunds=repository.db().query("SELECT b.*,pf.platform_status,pf.platform_quantity,pf.dispute_type FROM oms_refund b JOIN oms_platform_refund pf ON pf.company_code=b.company_code AND pf.id=b.platform_refund_id WHERE b.company_code=? AND b.order_id=? ORDER BY b.id",ROW,c,order);
        boolean pending=false;List<Map<String,Object>> triggers=new ArrayList<>();
        for(Map<String,Object> original:basis){long qty=number(original,"quantity"),confirmed=0,anticipated=0;BigDecimal difference=BigDecimal.ZERO;
            for(Map<String,Object> r:refunds){if(!text(original,"platform_oid").equals(text(r,"platform_oid")))continue;boolean closed="CLOSED".equals(text(r,"platform_status"))&&!"SUCCESS".equals(text(r,"funds_state"));if(closed)continue;
                boolean approved="APPROVED".equals(text(r,"review_state")),success="SUCCESS".equals(text(r,"funds_state"));String purpose=text(r,"purpose"),action=text(r,"goods_action");
                if(!approved){pending=true;continue;}if(Arrays.asList("DIFFERENCE","COMPENSATION","POSTAGE","OTHER","PLATFORM_SPECIAL").contains(purpose)){if(success&&"DIFFERENCE".equals(purpose))difference=difference.add(new BigDecimal(String.valueOf(r.get("refund_fee"))));continue;}
                long q="CANCEL".equals(action)?number(r,"cancel_quantity"):Arrays.asList("RETURN","REFUSAL","INTERCEPT").contains(action)?Math.min(qty,number(r,"platform_quantity")):0;
                if(q==0)continue;anticipated+=q;boolean fact=success||"DONE".equals(text(r,"goods_state"))&&number(r,"cancelled_quantity")>0;if(fact)confirmed+=q;else pending=true;
            }
            long left=Math.max(0,qty-confirmed),forecast=Math.max(0,qty-anticipated);Map<String,Object> actual=new LinkedHashMap<>(original),future=new LinkedHashMap<>(original);actual.put("quantity",left);actual.put("payment",proportional(original.get("payment"),left,qty));future.put("quantity",forecast);future.put("payment",proportional(original.get("payment"),forecast,qty));actual.put("difference_refund",difference);future.put("difference_refund",difference);effective.add(actual);projected.add(future);
        }
        for(Map<String,Object> r:refunds)if(!"CLOSED".equals(text(r,"platform_status"))||"SUCCESS".equals(text(r,"funds_state")))triggers.add(map("id",r.get("id"),"refund_sn",r.get("refund_sn"),"purpose",r.get("purpose"),"funds_state",r.get("funds_state"),"review_state",r.get("review_state"),"control_version",r.get("control_version")));
        Map<String,Object> snapshot=object(p.get("snapshot"));List<Map<String,Object>> eligible=retainedWithDifference(snapshot,effective,false),keepShipped=retainedWithDifference(snapshot,effective,true),forecast=retainedWithDifference(snapshot,projected,false);
        Map<String,Long> eligibleQty=quantities(eligible),shippedQty=quantities(keepShipped),forecastQty=quantities(forecast);List<Map<String,Object>> lines=repository.db().query("SELECT l.*,COALESCE((SELECT SUM(sl.shipped_quantity) FROM oms_order_shipment_line sl WHERE sl.company_code=l.company_code AND sl.order_line_id=l.id),0) shipped_quantity FROM oms_order_line l WHERE l.company_code=? AND l.order_id=? AND l.gift_plan_id=? ORDER BY l.id",ROW,c,order,p.get("id"));
        String block="";for(Map<String,Object> l:lines){long original=number(l,"quantity"),shipped=number(l,"shipped_quantity"),cancelled=number(l,"cancelled_quantity");String sku=text(l,"sku_sn");long desired=Math.max(0,original-eligibleQty.getOrDefault(sku,0L)),returnRequired=Math.min(shipped,Math.max(0,original-shippedQty.getOrDefault(sku,0L)));
            List<Map<String,Object>> plans=repository.db().query("SELECT id,refund_id,quantity,posted_quantity,accepted_quantity,waived_quantity,state,control_version,result_json FROM oms_refund_return_plan WHERE company_code=? AND gift_plan_id=? AND shipment_line_id IN (SELECT id FROM oms_order_shipment_line WHERE company_code=? AND order_line_id=?) ORDER BY id",ROW,c,p.get("id"),c,l.get("id"));
            returnRequired=Math.max(0,shipped-shippedQty.getOrDefault(sku,0L));
            for(Map<String,Object> rp:plans){rp.put("actual",rp.get("result_json")==null?null:object(rp.get("result_json")));rp.remove("result_json");}
            long returned=plans.stream().mapToLong(a->number(a,"posted_quantity")).sum(),arranged=plans.stream().mapToLong(a->number(a,"quantity")-number(a,"waived_quantity")).sum(),waived=repository.db().queryForObject("SELECT COALESCE(SUM(quantity),0) FROM oms_gift_resolution WHERE company_code=? AND plan_id=? AND order_line_id=? AND action='WAIVE' AND state='COMPLETED'",Long.class,c,p.get("id"),l.get("id"));
            waived+=plans.stream().mapToLong(a->number(a,"waived_quantity")).sum();
            long toCancel=Math.min(Math.max(0,original-cancelled-shipped),Math.max(0,desired-cancelled-returned-waived)),toReturn=Math.max(0,returnRequired-returned-waived),unarranged=Math.max(0,returnRequired-arranged-waived);
            l.putAll(map("eligible_quantity",eligibleQty.getOrDefault(sku,0L),"projected_eligible_quantity",forecastQty.getOrDefault(sku,0L),"cancel_required",toCancel,"return_required",toReturn,"unarranged_quantity",unarranged,"returned_quantity",returned,"waived_quantity",waived,"return_plans",plans,"pending_assessment",pending,"sources",repository.db().query("SELECT sl.*,sh.shipment_sn FROM oms_order_shipment_line sl JOIN oms_order_shipment sh ON sh.company_code=sl.company_code AND sh.id=sl.shipment_id WHERE sl.company_code=? AND sl.order_line_id=? AND sl.shipped_quantity>0 ORDER BY sl.id",ROW,c,l.get("id"))));
            boolean allocated=repository.db().queryForObject("SELECT COUNT(*) FROM oms_order_shipment_line sl JOIN oms_order_shipment sh ON sh.company_code=sl.company_code AND sh.id=sl.shipment_id WHERE sl.company_code=? AND sl.order_line_id=? AND sh.status NOT IN ('VOIDED','CLOSED') AND sl.quantity>sl.shipped_quantity+sl.cancelled_quantity",Long.class,c,l.get("id"))>0;l.put("needs_cutoff",allocated);
            boolean shortage=original-cancelled>number(l,"reserved_quantity");l.put("stock_shortage",shortage);
            String state=toCancel>0?(allocated?"WAIT_CUTOFF":"WAIT_CANCEL"):toReturn>0?(unarranged>0?"WAIT_RETURN":"RETURNING"):pending&&original>shipped+cancelled?"PENDING_REVIEW":returned>0?"RETURNED":waived>0?"WAIVED":cancelled>0?"CANCELED":shortage?"WAIT_STOCK":"ELIGIBLE";l.put("gift_state",state);
            l.put("next_action",toCancel>0?(allocated?"先撤回包含赠品的发货单，仓库确认后取消失效赠品；剩余正品重新分仓":"取消失效赠品并核对原库存回执"):toReturn>0?(unarranged>0?"选择关联退款单和实际发货来源，安排赠品退回":"跟进原退回包裹和THK实收入账"):pending?"售后尚未确认，赠品暂缓；撤销或驳回后恢复":shortage?"赠品库存不足，补货并重新预占后继续履约":"无需处理");
            if(toCancel>0)block="赠品售后处理未完成，请核对取消或截单结果";else if(pending&&original>shipped+cancelled&&block.isEmpty())block="赠品资格受进行中的售后影响，暂缓新增履约";else if(shortage&&block.isEmpty())block="赠品库存不足，等待补货并完成逻辑预占";
        }
        Map<String,Object> result=map("available",true,"id",p.get("id"),"order_id",order,"lines",lines,"triggers",triggers,"pending",pending,"block_reason",block,"effective_basis",effective,"projected_basis",projected,"snapshot",snapshot);
        String digest=hash(encode(result));if(!digest.equals(text(p,"assessment_hash"))){repository.db().update("UPDATE oms_gift_plan SET assessment=?,assessment_hash=?,control_version=control_version+1,last_error='' WHERE company_code=? AND id=?",encode(result),digest,c,p.get("id"));event(c,number(p,"id"),"ASSESS",block.isEmpty()?"已重新核对赠品资格及售后累计处理数量":block,"系统赠品核对");}
        repository.db().update("UPDATE oms_order SET gift_block_reason=?,control_version=control_version+IF(gift_block_reason<>?,1,0) WHERE company_code=? AND id=?",block,block,c,order);result.put("control_version",repository.db().queryForObject("SELECT control_version FROM oms_gift_plan WHERE company_code=? AND id=?",Long.class,c,p.get("id")));return result;
    }
    private static Map<String,Long> quantities(List<Map<String,Object>> list){Map<String,Long> out=new HashMap<>();for(Map<String,Object> r:list)out.put(text(r,"sku_sn"),number(r,"quantity"));return out;}
    private static List<Map<String,Object>> retainedWithDifference(Map<String,Object> snap,List<Map<String,Object>> basis,boolean shipped){List<Map<String,Object>> entitlements=new ArrayList<>();for(Map<String,Object> original:rows(snap.get("entitlements"))){Map<String,Object> single=new LinkedHashMap<>(snap);single.put("entitlements",Collections.singletonList(original));List<Map<String,Object>> input=new ArrayList<>();for(Map<String,Object> b:basis){Map<String,Object> copy=new LinkedHashMap<>(b);if(Boolean.TRUE.equals(object(original.get("policy")).get("difference_affects_amount")))copy.put("payment",new BigDecimal(String.valueOf(b.get("payment"))).subtract(new BigDecimal(String.valueOf(b.getOrDefault("difference_refund",0)))).max(BigDecimal.ZERO));input.add(copy);}entitlements.addAll(retained(single,input,shipped));}return aggregate(entitlements);}
    public Map<String,Object> report(String c,long order){Map<String,Object> result=tx().execute(s->{require(repository.db().queryForObject("SELECT COUNT(*) FROM oms_order WHERE company_code=? AND id=?",Long.class,c,order)==1,"订单不存在或无权访问");return assess(c,order);});if(Boolean.TRUE.equals(result.get("available")))result.put("events",repository.db().query("SELECT action,message,actor,create_time FROM oms_gift_event WHERE company_code=? AND plan_id=? ORDER BY id DESC LIMIT 100",ROW,c,result.get("id")));return result;}
    public Map<String,Object> previewNumber(String c,String number){require(number!=null&&!number.trim().isEmpty()&&number.length()<=64,"请填写OMS单号或平台单号");List<Long> ids=repository.db().queryForList("SELECT id FROM oms_order WHERE company_code=? AND (order_sn=? OR platform_tid=?) ORDER BY id LIMIT 2",Long.class,c,number.trim(),number.trim());require(ids.size()==1,"没有找到唯一业务订单，请使用OMS单号精确试算");return preview(c,ids.get(0));}
    public Map<String,Object> preview(String c,long order){Map<String,Object> o=repository.db().query("SELECT o.channel_id,p.processing_payload FROM oms_order o JOIN oms_platform_order p ON p.company_code=o.company_code AND p.id=o.platform_order_id WHERE o.company_code=? AND o.id=?",ROW,c,order).stream().findFirst().orElseThrow(()->new IllegalArgumentException("订单不存在或无权访问"));Map<String,Object> saved=plan(c,order,false);List<Map<String,Object>> basis=saved==null?repository.db().query("SELECT platform_oid,sku_sn,quantity,payment FROM oms_order_line WHERE company_code=? AND order_id=? AND gift_plan_id IS NULL AND business_type='SALE' AND bundle_id IS NULL",ROW,c,order):jsonRows(saved.get("basis_json"));return evaluate(published(c),number(o,"channel_id"),paidTime(text(o,"processing_payload")),basis);}
    public Map<String,Object> records(String c,Map<String,String> q){String where=" WHERE p.company_code=?";List<Object> args=new ArrayList<>(Collections.singletonList(c));String sn=q.getOrDefault("number","").trim();require(sn.length()<=64,"单号过长");if(!sn.isEmpty()){where+=" AND (o.order_sn=? OR o.platform_tid=?)";args.add(sn);args.add(sn);}long total=repository.db().queryForObject("SELECT COUNT(*) FROM oms_gift_plan p JOIN oms_order o ON o.company_code=p.company_code AND o.id=p.order_id"+where,Long.class,args.toArray());int page=Math.max(1,Integer.parseInt(q.getOrDefault("pageNum","1")));args.add((page-1)*20);List<Map<String,Object>> list=repository.db().query("SELECT p.id,p.order_id,p.channel_id,p.control_version,p.create_time,o.order_sn,o.platform_tid,o.gift_block_reason,p.initial_json,p.last_error FROM oms_gift_plan p JOIN oms_order o ON o.company_code=p.company_code AND o.id=p.order_id"+where+" ORDER BY p.id DESC LIMIT 20 OFFSET ?",ROW,args.toArray());for(Map<String,Object> row:list){row.put("gifts",jsonRows(row.remove("initial_json")));}return map("rows",list,"total",total);}
    public Map<String,Object> cancel(String c,long order,Map<String,Object> input,String actor){
        Map<String,Object> report=report(c,order);require(number(report,"control_version")==number(input,"control_version"),"赠品资格已变化，请刷新");Map<String,Object> line=rows(report.get("lines")).stream().filter(l->number(l,"id")==number(input,"order_line_id")).findFirst().orElseThrow(()->new IllegalArgumentException("赠品明细不属于当前订单"));require(number(line,"cancel_required")>0,"没有待取消的失效赠品");
        if(Boolean.TRUE.equals(line.get("needs_cutoff"))){Map<String,Object> o=repository.db().query("SELECT * FROM oms_order WHERE company_code=? AND id=?",ROW,c,order).get(0);if("PROCESSING".equals(text(o,"cutoff_state")))return map("state","WAIT_CUTOFF","message","原截单仍在处理中，请核对原结果");List<Long> shipments=repository.db().queryForList("SELECT DISTINCT sh.id FROM oms_order_shipment sh JOIN oms_order_shipment_line sl ON sl.company_code=sh.company_code AND sl.shipment_id=sh.id WHERE sh.company_code=? AND sh.order_id=? AND sl.order_line_id=? AND sh.status NOT IN ('VOIDED','CLOSED') AND sl.quantity>sl.shipped_quantity+sl.cancelled_quantity",Long.class,c,order,line.get("id"));cutoffs.request(c,order,map("control_version",o.get("control_version"),"mode","REPLAN","shipment_ids",shipments,"reason","售后取消失效赠品；保留其他商品待重新分仓"),actor);return map("state","WAIT_CUTOFF","message","已申请撤回相关发货单；仓库确认后继续取消赠品，正品保留待重新分仓");}
        long action=tx().execute(s->{Map<String,Object> current=assess(c,order);require(number(current,"control_version")==number(report,"control_version"),"赠品资格已变化，请刷新");Map<String,Object> l=rows(current.get("lines")).stream().filter(v->number(v,"id")==number(line,"id")).findFirst().get();List<Long> pending=repository.db().queryForList("SELECT id FROM oms_gift_resolution WHERE company_code=? AND plan_id=? AND order_line_id=? AND action='CANCEL' AND state='PENDING' FOR UPDATE",Long.class,c,report.get("id"),line.get("id"));if(!pending.isEmpty())return pending.get(0);
            long id=repository.insert("INSERT INTO oms_gift_resolution(company_code,plan_id,order_line_id,quantity,action,request_id,reason,evidence,actor) VALUES (?,?,?,?,'CANCEL',?,?,?,?)",c,report.get("id"),l.get("id"),l.get("cancel_required"),"GF"+token(),"售后后赠品条件不再满足","赠品资格快照 "+report.get("control_version"),actor);Map<String,Object> o=repository.db().query("SELECT channel_id,platform_tid FROM oms_order WHERE company_code=? AND id=?",ROW,c,order).get(0);Map<String,Object> command=map("request_id","CFGIFT"+id,"mode","REDUCE","channel_id",o.get("channel_id"),"platform_tid",text(l,"stock_reference").isEmpty()?o.get("platform_tid"):l.get("stock_reference"),"allocations",Collections.emptyList(),"demands",Collections.singletonList(map("platform_oid","","sku_sn",l.get("sku_sn"),"quantity",l.get("cancel_required"))));repository.db().update("UPDATE oms_gift_resolution SET command_json=? WHERE company_code=? AND id=?",encode(command),c,id);return id;});
        Map<String,Object> pending=repository.db().query("SELECT * FROM oms_gift_resolution WHERE company_code=? AND id=?",ROW,c,action).get(0),receipt=data(inventory.adjust(c,object(pending.get("command_json")),SecurityConstants.INNER));
        tx().execute(s->{Map<String,Object> locked=repository.db().query("SELECT * FROM oms_gift_resolution WHERE company_code=? AND id=? FOR UPDATE",ROW,c,action).get(0);if("COMPLETED".equals(text(locked,"state")))return null;require("COMPLETED".equals(text(receipt,"state")),"取消库存结果未确认，请沿用原请求重试");Map<String,Object> selected=rows(receipt.get("lines")).stream().filter(l->text(l,"platform_oid").isEmpty()&&text(l,"sku_sn").equals(text(line,"sku_sn"))).findFirst().orElseThrow(()->new IllegalArgumentException("赠品库存回执不完整"));repository.db().update("UPDATE oms_order_line SET cancelled_quantity=?,reserved_quantity=?,inventory_reason='售后取消失效赠品' WHERE company_code=? AND order_id=? AND id=? AND gift_plan_id=?",selected.get("cancelled_quantity"),selected.get("reserved_quantity"),c,order,line.get("id"),report.get("id"));repository.db().update("UPDATE oms_gift_resolution SET state='COMPLETED' WHERE company_code=? AND id=?",c,action);Map<String,Object> totals=repository.db().queryForMap("SELECT SUM(quantity-cancelled_quantity) required,SUM(reserved_quantity) reserved FROM oms_order_line WHERE company_code=? AND order_id=? AND business_type='SALE'",c,order);String stockState=number(totals,"required")==number(totals,"reserved")?"RESERVED":number(totals,"reserved")==0?"WAIT_RESERVE":"PART_RESERVED";repository.db().update("UPDATE oms_order SET inventory_status=?,review_status='PENDING',review_decision='MANUAL_REQUIRED',review_reason='赠品需求调整后待重新审核',allocation_status=IF(allocation_quantity>=?,'FULL',IF(allocation_quantity>0,'PART','NONE')),control_version=control_version+1 WHERE company_code=? AND id=?",stockState,number(totals,"required"),c,order);event(c,number(report,"id"),"CANCEL","已取消失效赠品 "+number(locked,"quantity")+" 件；原库存请求 CFGIFT"+action+"，未增加实物库存",actor);assess(c,order);return null;});return map("state","COMPLETED");
    }
    public Map<String,Object> waive(String c,long order,Map<String,Object> input,String actor){return tx().execute(s->{Map<String,Object> p=assess(c,order);require(number(input,"control_version")==number(p,"control_version")&&Boolean.TRUE.equals(input.get("confirmed")),"赠品信息已变化或尚未确认");Map<String,Object> l=rows(p.get("lines")).stream().filter(v->number(v,"id")==number(input,"order_line_id")).findFirst().orElseThrow(()->new IllegalArgumentException("赠品明细不存在"));long qty=number(input,"quantity");require(qty>0&&qty<=number(l,"unarranged_quantity"),"只能豁免尚未安排退回的已发赠品；已有安排请先截停并处理差异");boolean allowed=true;for(Map<String,Object> g:rows(object(p.get("snapshot")).get("entitlements")))if(text(g,"sku_sn").equals(text(l,"sku_sn"))&&!Boolean.TRUE.equals(object(g.get("policy")).get("allow_waive")))allowed=false;require(allowed,"原赠品策略不允许豁免追退");String reason=required(input,"reason",500),evidence=required(input,"evidence",1000);repository.db().update("INSERT INTO oms_gift_resolution(company_code,plan_id,order_line_id,quantity,action,state,request_id,reason,evidence,actor) VALUES (?,?,?,?,'WAIVE','COMPLETED',?,?,?,?)",c,p.get("id"),l.get("id"),qty,"GFW"+token(),reason,evidence,actor);event(c,number(p,"id"),"WAIVE","豁免追退 "+qty+" 件；原因："+reason+"；凭证："+evidence+"；不增加库存、不修改平台退款金额",actor);return assess(c,order);});}
    public void changed(String c,long order){if(repository.db().update("UPDATE oms_gift_plan SET dirty=1,next_check=NOW(),control_version=control_version+1 WHERE company_code=? AND order_id=?",c,order)>0)repository.giftChanged(c,order);}
    void guardCurrent(String c,Map<String,Object> order){Map<String,Object> assessment=assess(c,number(order,"id"));String block=text(assessment,"block_reason");order.put("gift_block_reason",block);require(block.isEmpty(),block);}
    public boolean isGiftPlan(String c,long refund,long plan){return repository.db().queryForObject("SELECT COUNT(*) FROM oms_refund_return_plan WHERE company_code=? AND refund_id=? AND id=? AND gift_plan_id IS NOT NULL",Long.class,c,refund,plan)==1;}
    void requireWaivePolicy(String c,long order,String sku){Map<String,Object> p=plan(c,order,true);require(p!=null,"赠品计划不存在");for(Map<String,Object> g:rows(object(p.get("snapshot")).get("entitlements")))if(sku.equals(text(g,"sku_sn")))require(Boolean.TRUE.equals(object(g.get("policy")).get("allow_waive")),"原赠品策略不允许豁免追退");}
    public void requireGiftPlan(String c,long refund,long plan){require(repository.db().queryForObject("SELECT COUNT(*) FROM oms_refund_return_plan WHERE company_code=? AND refund_id=? AND id=? AND gift_plan_id IS NOT NULL",Long.class,c,refund,plan)==1,"赠品退回安排不存在或无权访问");}
    void validateReturn(String c,Map<String,Object> refund,Map<String,Object> source,long qty,long excluded){
        Map<String,Object> report=assess(c,number(refund,"order_id"));require(number(report,"id")==number(source,"gift_plan_id"),"赠品来源不属于本订单的赠送计划");
        Map<String,Object> line=rows(report.get("lines")).stream().filter(l->number(l,"id")==number(source,"order_line_id")).findFirst().orElseThrow(()->new IllegalArgumentException("赠品原履约明细不存在"));
        long existing=excluded==0?0:repository.db().queryForObject("SELECT quantity-waived_quantity FROM oms_refund_return_plan WHERE company_code=? AND gift_plan_id=? AND id=?",Long.class,c,report.get("id"),excluded);
        require(qty>0&&qty<=number(line,"unarranged_quantity")+existing,"赠品应追回范围已变化、已安排或已豁免，请刷新核对");
    }
    public void process(String c,long order){Map<String,Object> p=plan(c,order,false);if(p==null)return;try{Map<String,Object> report=report(c,order);for(Map<String,Object> l:rows(report.get("lines")))if(number(l,"cancel_required")>0){cancel(c,order,map("control_version",report.get("control_version"),"order_line_id",l.get("id")),"系统赠品售后处理");break;}Map<String,Object> after=report(c,order);boolean pending=rows(after.get("lines")).stream().anyMatch(l->number(l,"cancel_required")>0);repository.db().update("UPDATE oms_gift_plan SET dirty=?,next_check=DATE_ADD(NOW(),INTERVAL 60 SECOND),last_error='' WHERE company_code=? AND id=? AND control_version=?",pending?1:0,c,p.get("id"),after.get("control_version"));}catch(RuntimeException e){repository.db().update("UPDATE oms_gift_plan SET dirty=1,next_check=DATE_ADD(NOW(),INTERVAL 60 SECOND),last_error=? WHERE company_code=? AND id=?",e instanceof IllegalArgumentException?String.valueOf(e.getMessage()).substring(0,Math.min(480,String.valueOf(e.getMessage()).length())):"赠品处理暂未确认，请核对原请求及仓库结果",c,p.get("id"));}}
    public void scan(String c){for(Long order:repository.db().queryForList("SELECT order_id FROM oms_gift_plan WHERE company_code=? AND order_id IS NOT NULL AND dirty=1 AND next_check<=NOW() ORDER BY next_check,id LIMIT 20",Long.class,c))process(c,order);}
}
